//! One private offline owner, explicit relative clock, timer insertion history,
//! and source raster for attack/end/first-idle, roofs, and Layer8 action3.
use super::{Model as Fire,CreateInputs,Inputs as FireInputs,ContinueInputs,RemoveInputs};
use crate::modern_lito::{native_appearance_inspection::{Binding,Dependencies},native_appearance_idle_study as idle,native_appearance_layer_study as layer,native_appearance_replay_study as replay,native_appearance_clock_study as clock,native_appearance_continuation_study as end,native_roof_callback_study::{multi as roof,Inputs as RoofInputs},native_resources::{NativeStaticAssets,NativeAssetPlan},native_action_inspection::NativeActionSnapshot,world_map::{WorldCell,ViewProjection},world_depth::NativeDrawCell,world_raster::{Raster,Blend},compositor::Canvas};
use anyhow::{ensure,Context,Result};use std::{collections::BTreeMap,sync::{Arc,atomic::{AtomicBool,Ordering}}};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) enum Kind{PlayerStart,PlayerAdvance,PlayerIdle,FireFirst,FireAdvance,Roof(u64),Locomotion(u64),IdleCycle(u64)}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) struct Event{pub serial:u64,pub at:u32,pub kind:Kind}
struct Identity{binding:Binding,plan:NativeAssetPlan,retired:AtomicBool}
pub(crate) struct Ticket{identity:Arc<Identity>,pub event:Event}
pub(crate) struct Frame{identity:Arc<Identity>,generation:u64,canvas:Canvas,pub clock:u32,pub kind:String,pub player_frame:Option<(u32,usize)>,pub fire_frame:Option<usize>}
pub(crate) struct DrawInputs{pub terrain_before_actors:Option<bool>,pub source_actor_redraw_history:Option<bool>,pub retained_pose_before_next_timer:Option<bool>}
pub(crate) enum Inputs{Player(layer::Inputs),Idle{callback:idle::Inputs,draw:layer::Inputs},FireFirst(FireInputs),FireAdvance(ContinueInputs),Roof(roof::TickInputs)}
#[derive(Clone,Copy)]struct Pose{bank:u32,sub:usize,idle:bool,cell:WorldCell,redraw:u64}
pub(crate) struct Model<'a>{identity:Arc<Identity>,player:idle::Model<'a>,layers:layer::Model,banks:&'a BTreeMap<u32,replay::Bank>,roof:roof::Model<'a>,fire:Fire<'a>,effect:&'a NativeActionSnapshot,fire_cell:WorldCell,view:ViewProjection,pose:Option<Pose>,fire_index:Option<usize>,fire_redraw:u64,events:Vec<Event>,serial:u64,generation:u64,last:u32,left:usize,player_hold_until:u32}
impl Identity{fn active(&self,b:&Binding,now:i64)->Result<()>{ensure!(!self.retired.load(Ordering::Acquire)&&self.binding==*b&&now>=b.observed&&(b.cutoff==-1||now<b.cutoff),"Scene retired/full owner/revision/cutoff");Ok(())}}
impl Frame{pub fn view<'a>(&'a self,model:&Model<'_>,b:&Binding,now:i64)->Result<&'a Canvas>{self.identity.active(b,now)?;ensure!(Arc::ptr_eq(&self.identity,&model.identity)&&self.generation==model.generation,"Foreign/stale scene output generation");Ok(&self.canvas)}}
fn draw_inputs(q:&DrawInputs)->Result<()>{ensure!(q.terrain_before_actors==Some(true)&&q.source_actor_redraw_history==Some(true)&&q.retained_pose_before_next_timer==Some(true),"Scene terrain/insertion/visible residency source unknown");Ok(())}
fn neutral()->layer::Inputs{layer::Inputs{draw_branch_reached:Some(true),actor_flags:Some(0),layer_flags:Some(0),base_shadow_route:Some(true),all_layer_pointers_present:Some(true)}}
fn paint<'r>(roof:&'r roof::Model<'_>,prepared:Option<&roof::Prepared>,layers:&layer::Model,banks:&'r BTreeMap<u32,replay::Bank>,b:&Binding,now:i64,view:ViewProjection,pose:Option<Pose>,fire_index:Option<usize>,fire_redraw:u64,effect:&'r NativeActionSnapshot,fire_cell:WorldCell,cancel:&AtomicBool)->Result<Canvas>{
 let mut canvas=Canvas::new(1024,768)?;let mut raster=Raster::new(view,&canvas);if let Some(p)=prepared{roof.submit_prepared(b,now,p,&mut raster)?;}else{roof.submit(b,now,&mut raster)?;}
 let player=if let Some(p)=pose{let bank=banks.get(&p.bank).context("Scene player bank missing")?;let list=if p.idle{layers.idle_cycle_submissions(b,now,p.bank,p.sub,&bank.body,&bank.shadow,&bank.layer,neutral())?}else{layers.submissions(b,now,p.bank,p.sub,&bank.body,&bank.shadow,&bank.layer,neutral())?};Some((p,list))}else{None};
 let submit_player=|r:&mut Raster<'r>|->Result<()>{if let Some((p,list))=&player{for s in list{r.sprite(NativeDrawCell::from_world(p.cell).context("Scene actor cell overflow")?,s.frame,if s.kind=="body"{1}else{0},if s.kind=="shadow"{Blend::Shadow}else{Blend::Over})?;}}Ok(())};
 let submit_fire=|r:&mut Raster<'r>|->Result<()>{if let Some(i)=fire_index{r.sprite(NativeDrawCell::from_world(fire_cell).context("Fire cell overflow")?,effect.scene_frame(i)?,0,Blend::Screen)?;}Ok(())};
 if pose.is_some_and(|p|p.redraw>fire_redraw){submit_fire(&mut raster)?;submit_player(&mut raster)?;}else{submit_player(&mut raster)?;submit_fire(&mut raster)?;}raster.paint(&mut canvas,cancel,1)?;Ok(canvas)
}
impl<'a> Model<'a>{
 pub fn new(enabled:bool,b:&Binding,now:i64,d:&'a Dependencies,banks:&'a BTreeMap<u32,replay::Bank>,assets:&'a NativeStaticAssets,plan:&NativeAssetPlan,effect:&'a NativeActionSnapshot,index:usize,initial:WorldCell,roof_input:&RoofInputs,create:&CreateInputs,ordinary:clock::OrdinaryInputs,end:end::EndInputs,view:Option<ViewProjection>,continuation_budget:Option<usize>)->Result<Self>{
  let first=ordinary.sampled_clock_ms.context("Player explicit startup clock unknown")?;let last=create.scheduler_sample_ms.context("Scene initial clock unknown")?;ensure!(first>=last&&roof_input.scheduler_sample_ms==Some(last)&&continuation_budget.is_some_and(|v|matches!(v,22|24|31)),"One source clock domain and explicit22or24or31 finite action3 continuation budget required");let view=view.context("Scene view projection unknown")?;ensure!(assets.geometry().contains(view.anchor_cell),"Scene foreign view");let player=idle::Model::new(enabled,d,b,b,now,0,ordinary,end)?;let layers=layer::Model::new(enabled,b,b,now,64)?;let roof=roof::Model::new(enabled,b,now,assets,plan,initial,roof_input,64)?;let mut fire=Fire::new(enabled,b,b,now,assets,plan,effect,index,create)?;fire.limit=continuation_budget.unwrap();let fire_due=fire.initial_due(b,now)?;let fire_cell=WorldCell{x:i32::from(fire.record.effect.x),y:i32::from(fire.record.effect.y)};
  let mut m=Self{identity:Arc::new(Identity{binding:b.clone(),plan:plan.clone(),retired:AtomicBool::new(false)}),player,layers,banks,roof,fire,effect,fire_cell,view,pose:None,fire_index:None,fire_redraw:0,events:Vec::new(),serial:0,generation:0,last,left:64,player_hold_until:first};m.insert(fire_due,Kind::FireFirst);m.insert(first,Kind::PlayerStart);Ok(m)
 }
 fn active(&self,b:&Binding,now:i64)->Result<()>{self.identity.active(b,now)?;ensure!(self.left>0&&self.identity.plan==*self.fire.assets.verified_plan(),"Scene budget/source mismatch");Ok(())}
 fn insert(&mut self,at:u32,kind:Kind){self.serial+=1;let e=Event{serial:self.serial,at,kind};let pos=self.events.partition_point(|old|old.at<=at);self.events.insert(pos,e);}
 fn sync_roof(&mut self,b:&Binding,now:i64)->Result<()>{let timers=self.roof.timers(b,now)?;self.events.retain(|e|match e.kind{Kind::Roof(s)=>timers.iter().any(|t|t.serial==s),_=>true});for t in timers{if !self.events.iter().any(|e|e.kind==Kind::Roof(t.serial)){self.insert(t.at,Kind::Roof(t.serial));}}Ok(())}
 pub fn next(&self,b:&Binding,now:i64)->Result<Ticket>{self.active(b,now)?;Ok(Ticket{identity:self.identity.clone(),event:*self.events.first().context("Finite scene has no scheduled callback")?})}
 pub fn clock(&self,b:&Binding,now:i64)->Result<u32>{self.active(b,now)?;Ok(self.last)}
 fn frame(&mut self,canvas:Canvas,at:u32,kind:String)->Frame{self.generation+=1;self.left-=1;self.last=at;Frame{identity:self.identity.clone(),generation:self.generation,canvas,clock:at,kind,player_frame:self.pose.map(|p|(p.bank,p.sub)),fire_frame:self.fire_index}}
 pub fn move_actor(&mut self,b:&Binding,now:i64,input:&roof::MoveInputs,draw:&DrawInputs)->Result<Frame>{self.active(b,now)?;draw_inputs(draw)?;let at=input.actor.scheduler_sample_ms.context("Scene move clock unknown")?;ensure!(at>=self.last&&at<self.next(b,now)?.event.at&&at<=self.player_hold_until,"Scene movement overtakes timer/pose residency");let prepared=self.roof.prepare_move(b,now,input)?;let mut pose=self.pose.context("Player startup required before move")?;pose.cell=input.actor.new_cell.context("Scene new cell unknown")?;pose.redraw=self.generation+1;let canvas=paint(&self.roof,Some(&prepared),&self.layers,self.banks,b,now,self.view,Some(pose),self.fire_index,self.fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.roof.commit(b,now,prepared)?;self.pose=Some(pose);self.sync_roof(b,now)?;Ok(self.frame(canvas,at,"EXPLICIT_CONDITIONAL_48AFC0_POSITION_WRITE".into()))}
 pub fn dispatch(&mut self,b:&Binding,now:i64,ticket:&Ticket,input:Inputs,draw:&DrawInputs)->Result<Frame>{
  self.active(b,now)?;draw_inputs(draw)?;ensure!(Arc::ptr_eq(&self.identity,&ticket.identity)&&self.events.first()==Some(&ticket.event),"Stale/foreign scene timer identity");let e=ticket.event;ensure!(e.at>=self.last&&e.at<=self.player_hold_until,"Scene timer clock/retained player pose boundary");let mut pose=self.pose;let mut fire_index=self.fire_index;let mut fire_redraw=self.fire_redraw;let canvas;
  match(e.kind,input){
   (Kind::PlayerStart|Kind::PlayerAdvance,Inputs::Player(draw))=>{let(_,bank,sub,due)=self.player.attack_next(b,now)?;ensure!(due==e.at,"Scene player due differs");let source=self.banks.get(&bank).context("Player bank absent")?;let qualified=self.layers.submissions(b,now,bank,sub as usize,&source.body,&source.shadow,&source.layer,draw)?;ensure!(qualified.iter().map(|s|s.flags).collect::<Vec<_>>()==[0,0,5],"Scene requires explicit neutral player flags");let cell=self.roof.cell(b,now)?;pose=Some(Pose{bank,sub:sub as usize,idle:false,cell,redraw:self.generation+1});canvas=paint(&self.roof,None,&self.layers,self.banks,b,now,self.view,pose,fire_index,fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;let f=self.player.attack_sample(b,now,e.at,source,neutral())?;self.player_hold_until=f.next_due_ms;self.events.remove(0);self.insert(f.next_due_ms,if f.ended{Kind::PlayerIdle}else{Kind::PlayerAdvance});}
   (Kind::PlayerIdle,Inputs::Idle{callback,draw})=>{let p=self.player.preview(b,now,&callback)?;ensure!(p.dispatch_ms==e.at&&p.scheduler_sample_ms==e.at,"Scene idle clock differs");let source=self.banks.get(&p.bank).context("Idle bank absent")?;let qualified=self.layers.idle_submissions(b,now,p.bank,p.subframe as usize,&source.body,&source.shadow,&source.layer,draw)?;ensure!(qualified.iter().map(|s|s.flags).collect::<Vec<_>>()==[0,0,5],"Scene requires neutral idle flags");pose=Some(Pose{bank:p.bank,sub:p.subframe as usize,idle:true,cell:self.roof.cell(b,now)?,redraw:self.generation+1});canvas=paint(&self.roof,None,&self.layers,self.banks,b,now,self.view,pose,fire_index,fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.player.sample(b,now,source,&callback,neutral())?;self.player_hold_until=p.next_due_ms;self.events.remove(0);}
   (Kind::FireFirst,Inputs::FireFirst(input))=>{ensure!(input.static_source_roofs==Some(false),"Shared scene must use owned dynamic roof state");let(dispatch,sampled,next)=self.fire.preview_policy(b,now,&input,false)?;ensure!(dispatch==e.at&&sampled==e.at,"Scene FirePot clock differs");fire_index=Some(1);fire_redraw=self.generation+1;canvas=paint(&self.roof,None,&self.layers,self.banks,b,now,self.view,pose,fire_index,fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.fire.pending=None;self.fire.future=Some(next);self.fire.stopped=true;self.fire.current=1;self.fire.expected=Some(next);self.events.remove(0);self.insert(next,Kind::FireAdvance);}
   (Kind::FireAdvance,Inputs::FireAdvance(input))=>{ensure!(input.callback.static_source_roofs==Some(false),"Shared scene dynamic roof state required");let step=self.fire.continuation_policy(b,now,&input,false)?;ensure!(step.dispatch_ms==e.at&&step.sampled_ms==e.at,"Shared FirePot internal clock differs");fire_index=Some(step.frame);fire_redraw=self.generation+1;canvas=paint(&self.roof,None,&self.layers,self.banks,b,now,self.view,pose,fire_index,fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.fire.current=step.frame;self.fire.expected=Some(step.expected_ms);self.fire.future=Some(step.next_due_ms);self.fire.queued_repeat=step.ended;self.fire.continuations+=1;self.events.remove(0);self.insert(step.next_due_ms,Kind::FireAdvance);}
   (Kind::Roof(serial),Inputs::Roof(input))=>{let source=self.roof.next(b,now)?;ensure!(source.timer.serial==serial&&input.dispatch_ms==Some(e.at),"Scene roof source timer differs");let prepared=self.roof.prepare_tick(b,now,&source,&input)?;canvas=paint(&self.roof,Some(&prepared),&self.layers,self.banks,b,now,self.view,pose,fire_index,fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.roof.commit(b,now,prepared)?;self.events.remove(0);self.sync_roof(b,now)?;}
   _=>anyhow::bail!("Scene callback input kind mismatch"),
  }
  self.pose=pose;self.fire_index=fire_index;self.fire_redraw=fire_redraw;Ok(self.frame(canvas,e.at,format!("{:?}",e.kind)))
 }
 pub fn remove_fire(&mut self,b:&Binding,now:i64,at:u32,input:&RemoveInputs,draw:&DrawInputs)->Result<Frame>{self.active(b,now)?;draw_inputs(draw)?;ensure!(at>=self.last&&at<self.next(b,now)?.event.at&&at<=self.player_hold_until,"Removal clock crosses pending callback/residency");let canvas=paint(&self.roof,None,&self.layers,self.banks,b,now,self.view,self.pose,None,self.fire_redraw,self.effect,self.fire_cell,&self.identity.retired)?;self.fire.remove_from_sector(b,now,input)?;self.events.retain(|e|!matches!(e.kind,Kind::FireFirst|Kind::FireAdvance));self.fire_index=None;Ok(self.frame(canvas,at,"SOURCE_CONDITIONAL_SECTOR_FIREPOT_REMOVAL".into()))}
 pub fn retire(&mut self){self.identity.retired.store(true,Ordering::Release);self.events.clear();self.player.retire();self.layers.retire();self.roof.retire();self.fire.retire();}
}
impl Drop for Model<'_>{fn drop(&mut self){self.retire();}}
